python3 -c "
import csv
from datetime import datetime
from collections import defaultdict

def parse_timestamp(ts):
    if not ts:
        return None
    try:
        return datetime.strptime(ts, '%Y-%m-%d %H:%M:%S')
    except:
        try:
            return datetime.strptime(ts, '%Y-%m-%d %H:%M:%S.%f')
        except:
            return None

carrier_data = defaultdict(lambda: {'total_hours': 0.0, 'count': 0})

with open('/home/agent/workspace/bookstore_orders.csv', 'r') as f:
    reader = csv.DictReader(f)
    for row in reader:
        if row['fulfillment_status'] != 'Delivered':
            continue

        carrier = row['carrier_name']
        order_ts = parse_timestamp(row['order_timestamp'])
        actual_dt = parse_timestamp(row['actual_delivery_date'])

        if order_ts and actual_dt:
            hours = (actual_dt - order_ts).total_seconds() / 3600
            carrier_data[carrier]['total_hours'] += hours
            carrier_data[carrier]['count'] += 1

# Calculate averages and prepare output
results = []
for carrier, data in carrier_data.items():
    count = data['count']
    avg_hours = round(data['total_hours'] / count, 2) if count > 0 else 0.0
    results.append({
        'CarrierName': carrier,
        'DeliveredOrders': count,
        'AvgDeliveryHours': avg_hours
    })

# Sort by AvgDeliveryHours ascending (fastest first)
results.sort(key=lambda x: x['AvgDeliveryHours'])

# Print results
print('Carrier Delivery Time (sorted by AvgDeliveryHours asc):')
print('CarrierName,DeliveredOrders,AvgDeliveryHours')
for r in results:
    print(f\"{r['CarrierName']},{r['DeliveredOrders']},{r['AvgDeliveryHours']}\")
"

python3 -c "
import csv
from collections import defaultdict
from datetime import datetime

def parse_timestamp(ts):
    if not ts:
        return None
    try:
        return datetime.strptime(ts, '%Y-%m-%d %H:%M:%S')
    except:
        try:
            return datetime.strptime(ts, '%Y-%m-%d %H:%M:%S.%f')
        except:
            return None

carrier_data = defaultdict(lambda: {'total_hours': 0.0, 'count': 0})

with open('/home/agent/workspace/bookstore_orders.csv', 'r') as f:
    reader = csv.DictReader(f)
    for row in reader:
        if row['fulfillment_status'] != 'Delivered':
            continue
        carrier = row['carrier_name']
        order_ts = parse_timestamp(row['order_timestamp'])
        actual_dt = parse_timestamp(row['actual_delivery_date'])
        if order_ts and actual_dt:
            hours = (actual_dt - order_ts).total_seconds() / 3600
            carrier_data[carrier]['total_hours'] += hours
            carrier_data[carrier]['count'] += 1

results = []
for carrier, data in carrier_data.items():
    count = data['count']
    avg_hours = round(data['total_hours'] / count, 2) if count > 0 else 0.0
    results.append({
        'CarrierName': carrier,
        'DeliveredOrders': count,
        'AvgDeliveryHours': avg_hours
    })

results.sort(key=lambda x: x['AvgDeliveryHours'])

with open('/home/agent/workspace/carrier-delivery-time.csv', 'w', newline='') as f:
    writer = csv.writer(f)
    writer.writerow(['CarrierName', 'DeliveredOrders', 'AvgDeliveryHours'])
    for r in results:
        writer.writerow([r['CarrierName'], r['DeliveredOrders'], r['AvgDeliveryHours']])

print('Written carrier-delivery-time.csv')
"

